patches.before:
const Config = z.object({
	prefix: z.string().required(),
	suffix: z.string().default(""),
	complete: z.boolean().default(false),
	includeRuntimeContext: z.boolean().default(true)
});

patches.after:
/* DSHA_PERSONA_TEXT_COMPAT_V1: legacy user presets keep their original text. */
const CurrentConfig = z.object({
	prefix: z.string().required(),
	suffix: z.string().default(""),
	complete: z.boolean().default(false),
	includeRuntimeContext: z.boolean().default(true)
});
const Config = z.transform(z.object({
	prefix: z.string(),
	text: z.any().hidden(),
	suffix: z.string().default(""),
	complete: z.boolean().default(false),
	includeRuntimeContext: z.boolean().default(true)
}), value => CurrentConfig(!Object.hasOwn(value, "prefix") && typeof value.text === "string" ? { ...value, prefix: value.text } : value), true);
